import{_ as s,C as t,o as r,c as n,E as a,a2 as l}from"./chunks/framework.BdWD-ld-.js";const d="/joinwell52/assets/skill-side-effect-20261119/skill-side-effect-path.en.svg",k=JSON.parse(`{"title":"The skill says read-only. The permission grants write. Which wins?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"The skill says read-only. The permission grants write. Which wins?","date":"2026-11-19","published_date":"2026-11-19","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"When a skill's side-effect claim conflicts with its permissions and attempted action, which check prevents a write?","summary":"A review skill claims to be read-only while its permission file allows writing. We ran Bulbasaur static and call-time checks, then tested the corresponding CodeFlowMu boundaries.","cover":"/assets/skill-side-effect-20261119/skill-side-effect.cover.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Pinned Bulbasaur revision: 13 upstream tests and 6 synthetic assertions; CodeFlowMu: 3 schema and 6 operation-fact assertions; no real write","pageClass":"six-governance-article"},"headers":[],"relativePath":"en/research/2026-11-19-skill-says-read-only.md","filePath":"en/research/2026-11-19-skill-says-read-only.md","lastUpdated":null}`),c={name:"en/research/2026-11-19-skill-says-read-only.md"};function h(p,e,m,u,f,g){const i=t("ArticleCover"),o=t("ArticleTableScroll");return r(),n("div",null,[a(i,{image:"/assets/skill-side-effect-20261119/skill-side-effect.cover.png",kicker:"Engineering research · Skill boundaries",title:"The skill says read-only. The permission grants write. Which wins?",summary:"One skill promises to read. Its permission file allows writing. We brought the two claims together at validation and at the operation boundary.",version:"2026-11-19",languageHref:"/zh/research/2026-11-19-skill-says-read-only",languageLabel:"中文"}),a(o,{language:"en"}),e[0]||(e[0]=l('<h1 id="the-skill-says-read-only-the-permission-grants-write-which-wins" tabindex="-1">The skill says read-only. The permission grants write. Which wins? <a class="header-anchor" href="#the-skill-says-read-only-the-permission-grants-write-which-wins" aria-label="Permalink to &quot;The skill says read-only. The permission grants write. Which wins?&quot;">​</a></h1><p>You install a “code review” skill for an AI team. Its instructions sound restrained: read the change, identify risks, and leave the files alone. Then you notice a line in its permission file allowing writes to <code>out/*</code>.</p><p>The important question is not whether the author probably meant to write a report. It is <strong>what the system does when a skill&#39;s claim and its effective permissions disagree, both before installation and when a tool call arrives.</strong> A task&#39;s read-only boundary cannot be proved by the skill&#39;s name.</p><h2 id="one-contradictory-skill" tabindex="-1">One contradictory skill <a class="header-anchor" href="#one-contradictory-skill" aria-label="Permalink to &quot;One contradictory skill&quot;">​</a></h2><p><a href="https://github.com/mansura-habiba/bulbasaur-skill-cli/pull/25" target="_blank" rel="noreferrer">Mansura Habiba&#39;s Bulbasaur repository</a> recently merged a concrete approach: declare a side-effect ceiling for a skill, compare it with permission grants using the same operation-cost model, and apply the ceiling again to attempted operations. This is the author&#39;s own project, not an official AGENTSAFE implementation.</p><p>At the pinned merge revision, we made two synthetic skills. Both declared <code>read_only</code>. One allowed writing to <code>out/*</code>; the other had an empty write allowlist. We ran the actual validator, then asked the actual runtime decision code about a read and a proposed report write. <strong>The probe requested decisions only; it did not modify a file.</strong></p><table tabindex="0"><thead><tr><th>Skill and proposed action</th><th>Before-use validation</th><th>At-operation decision</th></tr></thead><tbody><tr><td>Read-only claim with <code>out/*</code> write grant</td><td>Fails: <code>declared=read_only</code>, <code>implied=reversible</code></td><td>Writing <code>out/report.txt</code> denied by the side-effect ceiling</td></tr><tr><td>Same conflicting configuration</td><td>Same</td><td>Reading <code>in/change.diff</code> allowed</td></tr><tr><td>Read-only claim with empty write allowlist</td><td>Passes</td><td>Writing <code>out/report.txt</code> denied by the empty allowlist</td></tr></tbody></table><p>All 13 upstream side-effect contract tests passed at this revision, as did our six additional assertions. These are two different checks: <strong>validation compares the promise with the configured permission; the runtime compares the attempted operation with the actual ceiling.</strong> Keeping only the second check would let a contradictory configuration reach deployment.</p><p><img src="'+d+'" alt="Comparison of the skill claim, permission grant, and operation check"></p><h2 id="asking-the-same-question-of-codeflowmu" tabindex="-1">Asking the same question of CodeFlowMu <a class="header-anchor" href="#asking-the-same-question-of-codeflowmu" aria-label="Permalink to &quot;Asking the same question of CodeFlowMu&quot;">​</a></h2><p>CodeFlowMu is our local multi-agent collaboration system. It has skill registration and a separate path that derives facts from proposed tool operations and checks negative boundaries. We ran two bounded comparisons against a pinned clean revision, <strong>without executing a tool</strong>.</p><p>First, its skill-record schema accepted a tool marked <code>low</code> risk that also listed a write permission; adding <code>side_effects: read_only</code> was rejected. The current record format <strong>does not express Bulbasaur&#39;s side-effect ceiling</strong>. That is not proof that a low-risk skill can write freely: <code>risk_level</code> is not a read-only promise, and a schema-valid record is not an operation authorization.</p><p>Second, we proposed reading and writing the same protected source path, changing only the tool name. The real operation-fact classifier marked the read as <code>read</code>, without a protected-write match. It marked the write as <code>write</code> and matched <code>NEG.PROTECTED.BOUNDARY.WRITE</code>. Six assertions passed. Thus, the tested action classifier did not mistake a write for a read merely because a skill is described as “review.” This stops at fact classification, not a full approval or execution. The current skill injector explicitly runs in stub mode; we did not reproduce a deployed read-only skill writing a file.</p><h2 id="three-pieces-of-evidence-for-one-call" tabindex="-1">Three pieces of evidence for one call <a class="header-anchor" href="#three-pieces-of-evidence-for-one-call" aria-label="Permalink to &quot;Three pieces of evidence for one call&quot;">​</a></h2><p>For a multi-agent team, ask three separate questions: What does this task permit? What does this skill promise and what permissions does it hold? What will this particular tool call actually change? The answers come from different places and must not impersonate each other.</p><p>Bulbasaur offers a useful order of checks: catch the declaration–permission conflict early, then decide again before an operation. CodeFlowMu can classify the tested action and protected target, but this round did not establish that skill claims, task authority, and each call are already joined in one contract. We <strong>have not confirmed a product defect or opened a development item</strong>. Before assessing a change, we need a live-skill experiment tying a versioned skill, effective grants, FCoP formal task boundaries, and operation facts to the same call.</p><p>If your team uses AI skills, put three columns beside one ordinary “read-only” skill: <strong>its claim, its configured grants, and one actual request</strong>. Which column still depends on a guess? That is where evidence is missing. The pinned revisions and exact scope are in our <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-11-19-skill-side-effects/00-report.en.md" target="_blank" rel="noreferrer">English experiment report</a>.</p>',17))])}const y=s(c,[["render",h]]);export{k as __pageData,y as default};
